/**
 * Static reference data used to decorate raw Match-V5 responses.
 *
 * The Match API only returns *ids* for champions, items and augments;
 * human-readable names, item kinds and augment rarities are resolved from static
 * data sources (Data Dragon for champions/items, Community Dragon for Arena
 * augments). The full tables live in `./data/*.json`, generated by
 * `npm run data:fetch`, so any real player's matches resolve — not just the
 * curated demo roster.
 *
 * The `MOCK_*` pools below are the curated subset the deterministic mock
 * generator draws from (see `./mock`), kept small so the seeded demo stays tidy.
 */

import championsData from "./data/champions.json";
import itemsData from "./data/items.json";
import augmentsData from "./data/augments.json";

export interface ChampionRef {
  id: number;
  name: string;
}

export type AugmentRarity = "Silver" | "Gold" | "Prismatic";

export interface AugmentRef {
  id: number;
  name: string;
  rarity: AugmentRarity;
  /** Short rules text, resolved from Community Dragon. */
  description: string;
}

export type ItemKind = "AD" | "AP" | "Tank" | "Boots";

export interface ItemRef {
  id: number;
  name: string;
  kind: ItemKind;
}

/** The complete reference tables (real Data Dragon / Community Dragon ids). */
export const CHAMPIONS: ChampionRef[] = championsData;
export const ITEMS: ItemRef[] = itemsData as ItemRef[];
export const AUGMENTS: AugmentRef[] = augmentsData as AugmentRef[];

const CHAMPION_BY_ID = new Map(CHAMPIONS.map((c) => [c.id, c]));
const AUGMENT_BY_ID = new Map(AUGMENTS.map((a) => [a.id, a]));
const ITEM_BY_ID = new Map(ITEMS.map((i) => [i.id, i]));

export function getChampion(id: number): ChampionRef | undefined {
  return CHAMPION_BY_ID.get(id);
}

export function getAugment(id: number): AugmentRef | undefined {
  return AUGMENT_BY_ID.get(id);
}

export function getItem(id: number): ItemRef | undefined {
  return ITEM_BY_ID.get(id);
}

